using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Shared state for the note-taking tool
// ---------------------------------------------------------------------------
List<string> notebook = [];

// ---------------------------------------------------------------------------
// Tools the agent can invoke
// ---------------------------------------------------------------------------
var searchTool = AIFunctionFactory.Create(SearchWeb, "search_web",
    "Search the web for a query and return a list of result snippets.");

var addNoteTool = AIFunctionFactory.Create(AddNote, "add_note",
    "Save a research note for later reference.");

var readNotesTool = AIFunctionFactory.Create(ReadNotes, "read_notes",
    "Read all research notes collected so far.");

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(openAiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var tools = new ChatOptions
{
    Tools = [searchTool, addNoteTool, readNotesTool],
    Temperature = 0.2f,
};

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
const string systemPrompt = """
    You are a research agent. When the user gives you a topic:
    1. Use the search_web tool to find relevant information (make 2-3 searches
       with different queries to get broad coverage).
    2. Use the add_note tool to record the most important facts, statistics,
       and insights you discover.
    3. After gathering enough information, use read_notes to review everything
       you collected.
    4. Finally, produce a well-structured summary with sections, key findings,
       and source URLs.
    Always cite your sources.
    """;

// ---------------------------------------------------------------------------
// Interactive loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        🔍  Research Agent  🔍           ║");
Console.WriteLine("╠══════════════════════════════════════════╣");
Console.WriteLine("║  Enter a topic to research, or 'quit'.  ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.ForegroundColor = ConsoleColor.Cyan;
    Console.Write("Topic> ");
    Console.ResetColor();

    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    List<ChatMessage> history =
    [
        new(ChatRole.System, systemPrompt),
        new(ChatRole.User, $"Research the following topic and provide a comprehensive summary:\n\n{topic}"),
    ];

    Console.ForegroundColor = ConsoleColor.DarkGray;
    Console.WriteLine("\n⏳ Researching… (the agent will search the web and take notes)\n");
    Console.ResetColor();

    var response = await client.GetResponseAsync(history, tools);

    Console.ForegroundColor = ConsoleColor.Green;
    Console.WriteLine("═══════════════  Research Summary  ═══════════════\n");
    Console.ResetColor();
    Console.WriteLine(response.Text);
    Console.WriteLine();
}

Console.WriteLine("Goodbye!");
return;

// ═══════════════════════════════════════════════════════════════════════════
// Tool implementations
// ═══════════════════════════════════════════════════════════════════════════

[Description("Search the web for a query and return a list of result snippets.")]
static async Task<string> SearchWeb(
    [Description("The search query")] string query)
{
    Console.ForegroundColor = ConsoleColor.Yellow;
    Console.WriteLine($"  🌐 Searching: \"{query}\"");
    Console.ResetColor();

    try
    {
        using var http = new HttpClient();
        http.DefaultRequestHeaders.Add("User-Agent", "ResearchAgent/1.0");

        // Use the DuckDuckGo Instant Answer API (no key required)
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        var doc = await http.GetFromJsonAsync<JsonElement>(url);

        var results = new List<string>();

        // Abstract
        var abstractText = doc.GetProperty("Abstract").GetString();
        var abstractUrl = doc.GetProperty("AbstractURL").GetString();
        if (!string.IsNullOrWhiteSpace(abstractText))
            results.Add($"[Summary] {abstractText} (Source: {abstractUrl})");

        // Related topics
        if (doc.TryGetProperty("RelatedTopics", out var related))
        {
            foreach (var item in related.EnumerateArray().Take(8))
            {
                var text = item.TryGetProperty("Text", out var t) ? t.GetString() : null;
                var link = item.TryGetProperty("FirstURL", out var u) ? u.GetString() : null;
                if (!string.IsNullOrWhiteSpace(text))
                    results.Add($"• {text} (URL: {link})");
            }
        }

        if (results.Count == 0)
            results.Add("No results found. Try a more specific query.");

        return string.Join("\n", results);
    }
    catch (Exception ex)
    {
        return $"Search failed: {ex.Message}. Try a different query.";
    }
}

[Description("Save a research note for later reference.")]
string AddNote(
    [Description("The note content to save")] string note)
{
    notebook.Add(note);
    Console.ForegroundColor = ConsoleColor.Magenta;
    Console.WriteLine($"  📝 Note #{notebook.Count} saved");
    Console.ResetColor();
    return $"Note #{notebook.Count} saved successfully.";
}

[Description("Read all research notes collected so far.")]
string ReadNotes()
{
    if (notebook.Count == 0)
        return "No notes have been saved yet.";

    Console.ForegroundColor = ConsoleColor.Magenta;
    Console.WriteLine($"  📖 Reading {notebook.Count} note(s)");
    Console.ResetColor();

    return string.Join("\n", notebook.Select((n, i) => $"Note #{i + 1}: {n}"));
}

